from fastapi import APIRouter, Depends, HTTPExceptionfrom sqlalchemy.orm import Sessionfrom .. import crud, schemas, database, configfrom ..auth import get_current_userrouter = APIRouter(prefix="/admin", tags=["admin"])settings = config.settingsdef admin_only(user = Depends(get_current_user)):    if not user.is_admin:        raise HTTPException(status_code=403, detail="Admin access required")    return user@router.post("/users", dependencies=[Depends(admin_only)], response_model=schemas.UserOut)def create_user(user_in: schemas.UserCreate, db: Session = Depends(database.get_db)):    user = crud.create_user(db, user_in.username, user_in.password, user_in.is_admin, user_in.credits)    return user@router.post("/users/{user_id}/credits", dependencies=[Depends(admin_only)])def add_credits(user_id: int, amount: int, db: Session = Depends(database.get_db)):    user = crud.add_credits(db, user_id, amount)    if not user:        raise HTTPException(status_code=404, detail="User not found")    return {"ok": True, "user": {"id": user.id, "username": user.username, "credits": user.credits}}